"""Contract for scripts/check-requirements-lock.py (offline lock staleness check)."""
from __future__ import annotations

import importlib.util
from pathlib import Path

SCRIPT_PATH = Path(__file__).resolve().parents[1] / "scripts" / "check-requirements-lock.py"
SPEC = importlib.util.spec_from_file_location("survng_check_requirements_lock", SCRIPT_PATH)
assert SPEC is not None and SPEC.loader is not None
LOCK = importlib.util.module_from_spec(SPEC)
SPEC.loader.exec_module(LOCK)

LOCK_TEXT = """\
# This file was autogenerated by uv via the following command:
#    scripts/lock-requirements.sh
fastapi==0.150.0 \\
    --hash=sha256:00
    # via -r requirements.txt
pillow==12.3.0 ; sys_platform == 'darwin' \\
    --hash=sha256:11
    # via -r requirements.txt
starlette==1.0.0 \\
    --hash=sha256:22
    # via fastapi
uvicorn==0.54.0 \\
    --hash=sha256:33
    # via
    #   -r requirements.txt
    #   other
"""

REQUIREMENTS = """\
fastapi>=0.141.1,<1
uvicorn[standard]>=0.52.4,<1  # server
Pillow>=12.3.0,<13; platform_system=="Darwin"
"""


def _write(tmp_path: Path, requirements: str, lock: str = LOCK_TEXT) -> tuple[Path, Path]:
    req = tmp_path / "requirements.txt"
    req.write_text(requirements, encoding="utf-8")
    lock_path = tmp_path / "requirements.lock"
    lock_path.write_text(lock, encoding="utf-8")
    return req, lock_path


def test_current_lock_passes(tmp_path):
    assert LOCK.check(*_write(tmp_path, REQUIREMENTS)) == []


def test_unsatisfied_range_and_missing_pin_fail(tmp_path):
    problems = LOCK.check(*_write(tmp_path, REQUIREMENTS.replace(">=0.141.1", ">=0.151") + "newpkg>=1\n"))
    assert any("fastapi" in problem and "0.150.0" in problem for problem in problems)
    assert any(problem.startswith("newpkg>=1 has no pin") for problem in problems)


def test_removed_direct_requirement_fails(tmp_path):
    problems = LOCK.check(*_write(tmp_path, "fastapi>=0.141.1,<1\n"))
    assert len(problems) == 2
    assert any("pillow" in problem for problem in problems)
    assert any("uvicorn" in problem for problem in problems)


def test_repository_lock_is_current():
    root = SCRIPT_PATH.parents[1]
    assert LOCK.check(root / "requirements.txt", root / "requirements.lock") == []
